300	/**
301	 * Build the tree this call pushes, in an index of its own.
302	 *
303	 * `GIT_INDEX_FILE` is set for these commands and never on `process.env`: the run's own
304	 * checkout has an index, and a tool call that left the variable set would silently
305	 * redirect the next `git` in the same process — a `commit_and_push`, say — at a tree
306	 * holding nothing but drafts. Each helper below is one step of the same shape: read a
307	 * tree into the temporary index, change one thing, write it back out.
308	 */
309	function gitInIndex(indexPath: string, args: string[]): ReturnType<typeof gitRunWith> {
310	  return gitRunWith(indexEnv(indexPath), ...args);
311	}
312	
313	function gitInIndexStdin(indexPath: string, args: string[], input: string): ReturnType<typeof gitRunWith> {
314	  return gitRunWith({ ...indexEnv(indexPath), stdin: input }, ...args);
315	}
316	
317	/** The repository whose blob URLs a published draft is reported against, as `owner/name`. */
318	function resolveRepo(): string {
319	  const fromEnv = (process.env.GITHUB_REPOSITORY ?? "").trim();
320	  if (fromEnv) return fromEnv;
321	  // Same fallback `mcp/github.ts` uses: the checkout's own remote.
322	  const { code, stdout } = gitRun("remote", "get-url", "origin");
323	  if (code === 0 && stdout) {
324	    const match = /github\.com[/:](.+\/.+?)(?:\.git)?$/.exec(stdout.trim());
325	    if (match) return match[1]!;
326	  }
327	  throw new Error(
328	    "GITHUB_REPOSITORY is unset and no GitHub remote could be read, so there is no repository to report a published draft against.",
329	  );
330	}

