348	/** The URL as an attachment address, or the refusal naming what this tool does read. */
349	export function attachmentUrlFrom(raw: string): URL {
350	  let url: URL;
351	  try {
352	    url = new URL(raw);
353	  } catch {
354	    throw new Error(`${raw} is not an absolute URL.`);
355	  }
356	  if (!attachmentUrlAllowed(url)) {
357	    throw new Error(
358	      `${raw} is not an attachment this tool fetches. It reads ` +
359	        "`https://github.com/user-attachments/files/<id>/<name>` and " +
360	        "`https://private-user-images.githubusercontent.com/...`, and refuses every other host: what it does with " +
361	        "the answer is write a file, and the URL is the caller's.",
362	    );
363	  }
364	  return url;
365	}
