474	    }
475	  }
476	
477	  mkdirSync(dirname(dest), { recursive: true });
478	  writeFileSync(dest, Buffer.concat(chunks));
479	
480	  log(`fetch_attachment ${bytes}B ${contentType ?? "(no content-type)"} in ${Date.now() - started}ms`);
481	  return { bytes, contentType };
482	}
